import{z as s,x as m,o as E,c as p,q as t,j as A,D as e,d as l,s as o,S as B,b as i}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"通信原语与 overlap","description":"","frontmatter":{"title":"通信原语与 overlap","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-comm-overlap.md","filePath":"llm/dist-comm-overlap.md","lastUpdated":1791063341000}'),d={name:"llm/dist-comm-overlap.md"};function n(c,a,h,C,D,P){const r=m("Mermaid");return E(),p("div",null,[a[2]||(a[2]=t('<h1 id="通信原语与-overlap" tabindex="-1">通信原语与 overlap <a class="header-anchor" href="#通信原语与-overlap" aria-label="Permalink to &quot;通信原语与 overlap&quot;">​</a></h1><div class="epigraph"><p>重叠不减少一个字节，它只把加法改成取 max；合法性由依赖图决定，不由 stream 的数量决定。</p><footer>—— 据 NVIDIA NCCL 文档与 Megatron-LM 的重叠实践整理</footer></div><p><a href="/llm/dist-activation-recompute">上一课</a>把反向拉长了，也把反向里可以排通信的窗口拉长。本课从原语出发把通信说全：每种原语对应哪种并行的哪次交换、哪些对在关键路径上、哪些能被挪走。主干课的 <a href="/llm/tp-comm-overlap">TP 通信重叠</a>与<a href="/llm/comp-comm-overlap">计算通信重叠</a>写了两个具体场景；本课给一张全图，并把「合法重叠」的判据说清。不重讲 ring 与 tree 的内部实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通信写进 step time 有两种方式：关键路径上的等待，与可以遮住却没遮住的暴露。分不清这两者，优化就打偏：给已经重叠的 DP 梯度换更快的算法，收益接近零；放着层内关键路径上的 All-Reduce 不动去调桶大小，也是白忙。第二类错是假重叠：计算流与通信流都建了，内核却因争抢同一份缓冲或同一组 SM 串行了，trace 上看两个 kernel「都在跑」，step time 一毫秒没降。第三类错是非法重叠：通信开始读一块计算还没写完的数据，结果静默错——它不报错，只在 loss 曲线上留毛刺。</p><h3 id="原语到并行的映射" tabindex="-1">原语到并行的映射 <a class="header-anchor" href="#原语到并行的映射" aria-label="Permalink to &quot;原语到并行的映射&quot;">​</a></h3><p>承接第一课的表，给通信侧视图：DP 梯度走 All-Reduce，或 ZeRO 二三档的 Reduce-Scatter 加 All-Gather；TP 每层正反向各一次 All-Reduce，序列并行后拆成 RS 加 AG 的对；PP 走点对点；EP 走两次 All-to-All；CP 按 Ulysses 走 All-to-All、按 Ring 走点对点；Broadcast 只出现在初始化与元数据。判「能不能遮」的第一性依据是：这次交换的消费方是谁——DP 的梯度平均不喂任何当前计算，天生可遮；TP 的层内 All-Reduce 直接喂下一层，天生在关键路径上，只能靠改切分把它变短。</p><p><span class="marginnote">「All-Reduce」翻译一下：每张卡都交出自己的一份（如本地梯度），最后每张卡都拿到全体之和（或平均）。它是一组卡的「集体作业」，谁晚到全体都得等——这就是它出现在关键路径上时特别贵的原因。同族的 Reduce-Scatter 只发「每人一份碎片」，All-Gather 再把碎片拼回全量。</span></p><p><span class="marginnote">通信 dtype 是时序的一部分：梯度以 BF16 通信字节数减半，FP8 再减一半，但缩放协议要在所有副本对齐。同样的 overlap 计划换 dtype 后，桶边界与就绪时刻都变，要重排而不是照搬。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合法重叠只有四类结构。其一是分桶流水：梯度按桶切，前几个桶算完就发，反向继续算——DP 与 ZeRO 的默认形态。其二是窗口挪移：把可遮通信挪到没有依赖的时段，例如 PP 在算当前 microbatch 时递交上一阶段的激活。其三是拆依赖：序列并行把 Norm 后的激活切开，让 AG 的 g 区与 RS 部分先走，把不可遮部分压缩成每层一次的纯 AR。其四是异步分档：优化器分片的更新与下一步的前向重叠，前提是读的参数是上一步版本。四类之外的「重叠」都要先过依赖审查：被挪的通信不得消费未就绪数据，跨流同步用事件写明，CUDA Graph 必须把通信流一起收进去。</p><p><span class="marginnote">「事件同步」翻译一下：事件是插在 GPU 任务流上的一个路闸——计算流跑到「梯度桶就绪」处点亮事件，通信流看到灯亮才发车。没有这道闸，通信可能在数据只写了一半时就开始读，结果不报错但数值悄悄错。闸的位置必须精确到「真的就绪」那一刻，不能凭感觉提前。</span></p>',12)),(E(),A(B,null,{default:e(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E4%B8%80%E6%AC%A1%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%22%5D%20--%3E%20WHO%7B%22%E6%B6%88%E8%B4%B9%E6%96%B9%E6%98%AF%E8%B0%81%3F%22%7D%0A%20%20WHO%20--%3E%7C%E4%B8%8D%E5%96%82%E5%BD%93%E5%89%8D%E8%AE%A1%E7%AE%97%7C%20FREE%5B%22%E5%8F%AF%E9%81%AE%3A%20%E5%88%86%E6%A1%B6%E6%B5%81%E6%B0%B4%E6%88%96%E7%AA%97%E5%8F%A3%E6%8C%AA%E7%A7%BB%22%5D%0A%20%20WHO%20--%3E%7C%E7%9B%B4%E6%8E%A5%E5%96%82%E4%B8%8B%E4%B8%80%E5%B1%82%7C%20CRIT%5B%22%E5%85%B3%E9%94%AE%E8%B7%AF%E5%BE%84%3A%20%E6%94%B9%E5%88%87%E5%88%86%E5%8F%98%E7%9F%AD%2C%20%E6%88%96%E6%8B%86%E4%BE%9D%E8%B5%96%22%5D%0A%20%20FREE%20--%3E%20GUARD%5B%22%E4%BA%8B%E4%BB%B6%E5%90%8C%E6%AD%A5%20%2B%20%E5%8F%8C%E6%B5%81%20%2B%20%E7%BC%93%E5%86%B2%E4%B8%8D%E5%85%B1%E7%94%A8%22%5D%0A%20%20CRIT%20--%3E%20GUARD%0A%20%20GUARD%20--%3E%20TRACE%5B%22%E7%94%A8%20trace%20%E9%AA%8C%E8%AF%81%E7%9C%9F%E5%B9%B6%E5%8F%91%2C%20%E4%B8%8D%E7%9C%8B%E6%B5%81%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[l("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),(E(),A(B,null,{default:e(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E6%97%A0%E9%87%8D%E5%8F%A0%EF%BC%9A%E4%B8%B2%E8%A1%8C%22%5D%20--%3E%20T1%5B%22step%20time%20%E2%89%88%20T_comp%20%2B%20T_comm%22%5D%0A%20%20T1%20--%3E%20P%5B%22%E9%83%A8%E5%88%86%E9%87%8D%E5%8F%A0%EF%BC%9A%E6%A1%B6%E5%86%85%E5%85%88%E7%AE%97%E5%AE%8C%E7%9A%84%E5%85%88%E5%8F%91%22%5D%0A%20%20P%20--%3E%20T2%5B%22step%20time%20%E4%BB%8B%E4%BA%8E%E4%B8%A4%E8%80%85%E4%B9%8B%E9%97%B4%22%5D%0A%20%20T2%20--%3E%20I%5B%22%E7%90%86%E6%83%B3%E9%87%8D%E5%8F%A0%EF%BC%9A%E5%AE%8C%E5%85%A8%E9%81%AE%E4%BD%8F%22%5D%0A%20%20I%20--%3E%20T3%5B%22step%20time%20%E2%89%88%20max(T_comp%2C%20T_comm)%22%5D%0A%20%20T3%20--%3E%20CAP%5B%22%E4%B8%8A%E9%99%90%EF%BC%9A%E9%80%9A%E4%BF%A1%E5%BF%85%E9%A1%BB%E7%AD%89%E6%9C%80%E5%90%8E%E4%B8%80%E4%B8%AA%E4%BE%9D%E8%B5%96%E5%B0%B1%E7%BB%AA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>收益的解析式：理想重叠下 \\(T \\approx \\max(T_{\\mathrm{comp}}, T_{\\mathrm{comm}})\\)，部分重叠是两者之间的插值，插值系数由被遮住的字节数比例决定。桶大小是插值的旋钮：桶大，启动开销摊得薄，但暴露窗口来得晚，步末堆积；桶小，遮得早，启动次数把延迟项抬起来。最优桶与单桶计算时间同量级，且随 dtype 变。TP 层内通信为什么难遮：它的消费方是紧接着的 GEMM；序列并行之所以有效，是把那次 All-Reduce 拆成「可提前的 RS 加不可提前的 AG」，把可遮部分剥出去——重叠上限是被依赖结构决定的，不是被算法选择决定的。</p><p><span class="marginnote">代个数字看重叠值多少：设一步计算 2 秒、通信 1 秒。不重叠是 \\(2+1=3\\) 秒；理想重叠后取 max 即 2 秒，省三分之一。但通信里若有半秒在等数据就绪，实际只能压到 2.5 秒——「预算 1 秒通信」和「真被遮住 1 秒」是两回事，这半秒就是 trace 要抓的暴露窗口。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ring 与 tree 的选择、算法与协议的匹配、自定义 allreduce 的阈值，见 <a href="/llm/ring-tree-allreduce">Ring / Tree allreduce</a>、<a href="/llm/nccl-algorithms">NCCL 算法选择</a>与<a href="/llm/custom-allreduce">自定义 allreduce</a>，本课不重复；调参口径见 <a href="/llm/nccl-tuning">NCCL 调优</a>。非法重叠不能靠功能测试兜住：数值错不立即显形，要在小规模上做「关重叠对拍」。判真并发的标准是 trace 上计算与通信的核占用不互相挤兑，而不是两条流存在。桶与 dtype 每改一次，重叠计划重排一次——它们是同一个时间线上的变量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原语到并行的映射固定：AR 与 RS/AG 归 DP 侧，层内 AR 归 TP，P2P 归 PP，A2A 归 EP 与 CP。</li><li>可遮性由依赖结构决定：不喂当前计算的通信天生可遮，喂下一层的只能靠改切分变短。</li><li>合法重叠四类：分桶流水、窗口挪移、拆依赖、异步分档；其余先过依赖审查。</li><li>桶大小与通信 dtype 是同一时间线的旋钮，改一个要重排另一个。</li><li>假重叠与非法重叠都要靠 trace 与对拍抓，不看流是否存在。</li><li>出处：NCCL 公开文档；Shoeybi 等 Megatron-LM 的序列并行与重叠口径。</li></ul>',6))])}const _=s(d,[["render",n]]);export{T as __pageData,_ as default};
